#![allow(clippy::double_must_use)] // Async methods generated by `rpc` add `must_use`.

//! Moves the dev node's block clock forward, so tests can reach timestamps without waiting for them.

use crate::node::DEV_TIME_OFFSET_SECS;
use jsonrpsee::{core::RpcResult, proc_macros::rpc};
use std::sync::atomic::Ordering;

#[rpc(server, namespace = "tempo")]
pub trait TempoDevClockApi {
    /// Adds `seconds` to the offset the dev miner adds to wall-clock time, and returns the new offset.
    ///
    /// The offset only grows, so block timestamps stay monotonic.
    #[method(name = "devIncreaseTime")]
    async fn dev_increase_time(&self, seconds: u64) -> RpcResult<u64>;

    /// Returns the offset, in seconds, the dev miner adds to wall-clock time.
    #[method(name = "devTimeOffset")]
    async fn dev_time_offset(&self) -> RpcResult<u64>;
}

/// The `tempo_dev*` clock methods, registered only on a `--dev` node.
#[derive(Debug, Clone, Default)]
pub struct TempoDevClock;

impl TempoDevClockApiServer for TempoDevClock {
    async fn dev_increase_time(&self, seconds: u64) -> RpcResult<u64> {
        let previous = DEV_TIME_OFFSET_SECS.fetch_add(seconds, Ordering::SeqCst);
        Ok(previous.saturating_add(seconds))
    }

    async fn dev_time_offset(&self) -> RpcResult<u64> {
        Ok(DEV_TIME_OFFSET_SECS.load(Ordering::SeqCst))
    }
}
